  --eco-primary:#415b46; --eco-secondary:#304835; --eco-glow:transparent; --eco-subtle:#e5ecdf;
  --text-primary:var(--ink); --text-secondary:#5d685f; --text-muted:#69736a;
  --border-subtle:1px solid var(--line); --border-glow:1px solid #aaba9f;
  --shadow-glow:none; --shadow-card:0 14px 40px #283e3408; --shadow-mega:0 30px 80px #283e3420;
  --nav-bg:#f8f7f2f0; --gradient-eco:linear-gradient(110deg,#415b46,#415b46);
  --private-color:#405b45; --private-bg:#e4ecde; --private-border:#c1d0b8; --private-glow:transparent;
  --business-color:#755d52; --business-bg:#efe2db; --business-border:#ddc9bd; --business-glow:transparent;
  --switch-bg:#e9ece3; --radius-sm:6px; --radius-md:12px; --radius-lg:18px;
  --ba-accent:#718163; --ba-accent-hover:#526347;
  --primary:#536d40; --text:var(--ink); --border:#d8ddd0; --surface:#f5f7ed; color-scheme:light;
}
