@media(prefers-reduced-motion:reduce) {
  *,*:before,*:after {animation:none!important; transition:none!important; scroll-behavior:auto!important;}
  .reveal.is-pending {opacity:1; translate:none;} .hero-placeholder>#interiorImage {transform:none;}
}

/* Narrow home cards and booking heading: preserve readable, intrinsic sizing. */
@media (max-width: 480px) {
  body:has(#interiorImage) .services .services-grid { grid-template-columns: minmax(0, 1fr); }
  body:has(#interiorImage) .services .service-card:not(.service-card-featured) { min-height: 0; }
  body:has(#interiorImage) .services .service-title { overflow-wrap: anywhere; }
  body:has(#interiorImage) .price-configurator .config-header { flex-wrap: wrap; align-items: flex-start; }
  body:has(#interiorImage) .price-configurator .config-header h3 { min-width: 0; }
  body:has(#interiorImage) .price-configurator .config-status { flex: 0 0 auto; margin-left: 0; }
}

/* Editorial process numerals: remove the inherited neon circle and grid stretch. */
body:has(#interiorImage) .how-it-works .step-number {
  position: static;
  display: block;
  align-self: start;
  justify-self: start;
  width: max-content;
  height: auto;
  border: 0;
  border-bottom: 1px solid #c4aa8d;
  border-radius: 0;
  background: none;
  box-shadow: none;
  padding: 0 4px 14px 0;
  margin: 0 0 28px;
  font-family: var(--font-display);
  font-size: 76px;
  font-style: normal;
  font-weight: 400;
  font-variant-numeric: lining-nums;
  letter-spacing: -.04em;
  line-height: .95;
  color: #74856a;
}
body:has(#interiorImage) .how-it-works .step-number::before { content: '0'; }
body:has(#interiorImage) .how-it-works .step-number::after { content: none; }
@media (max-width: 700px) {
  body:has(#interiorImage) .how-it-works .step-number {
    font-size: 52px;
    padding-bottom: 12px;
    margin: 0;
  }
}

edits.after:
@import url('../style.css') layer(legacy);
@import url('../mobile.css') layer(legacy);
@import url('../large-order-panel.css') layer(legacy);
@import url('../before-after-slider.css') layer(legacy);
@import url('../reviews.css') layer(legacy);

/* Atelier palette. Legacy layout is retained underneath a single design layer. */
:root, [data-theme="light"] {
  --paper:#f8f7f2; --ink:#283e34; --muted:#69736a; --sage:#dce5d9; --blush:#ecdcd5;
  --line:#d8ddd3; --font-main:'Manrope',sans-serif; --font-display:'Cormorant Garamond',Georgia,serif;
  --bg-primary:var(--paper); --bg-secondary:#eef1e9; --bg-tertiary:#e7ece2; --bg-card:#fffef9;
  --eco-primary:#415b46; --eco-secondary:#304835; --eco-glow:transparent; --eco-subtle:#e5ecdf;
  --text-primary:var(--ink); --text-secondary:#5d685f; --text-muted:#69736a;
  --border-subtle:1px solid var(--line); --border-glow:1px solid #aaba9f;
  --shadow-glow:none; --shadow-card:0 14px 40px #283e3408; --shadow-mega:0 30px 80px #283e3420;
  --nav-bg:#f8f7f2f0; --gradient-eco:linear-gradient(110deg,#415b46,#415b46);
  --private-color:#405b45; --private-bg:#e4ecde; --private-border:#c1d0b8; --private-glow:transparent;
  --business-color:#755d52; --business-bg:#efe2db; --business-border:#ddc9bd; --business-glow:transparent;
  --switch-bg:#e9ece3; --radius-sm:6px; --radius-md:12px; --radius-lg:18px;
  --ba-accent:#718163; --ba-accent-hover:#526347;
  --primary:#536d40; --text:var(--ink); --border:#d8ddd0; --surface:#f5f7ed; color-scheme:light;
}
html {scroll-padding-top:110px; scroll-behavior:smooth;}
body {background:var(--paper); color:var(--ink); font-family:var(--font-main); font-size:16px; line-height:1.65; overflow-x:clip;}
button,input,select,textarea {font-family:inherit; font-size:inherit;}
button,a,input,select,textarea { -webkit-tap-highlight-color:transparent; }
button {cursor:pointer;}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible {outline:2px solid #597443; outline-offset:5px;}
::selection {background:#d9e4cd; color:#263c2a;}
section {scroll-margin-top:90px;}
img {max-width:100%;}
.section-container,.booking-container,.gr-inner,.footer-grid,.footer-bottom {max-width:1320px; width:calc(100% - 112px); margin-inline:auto;}
